'use strict';
const $=id=>document.getElementById(id),catalog=window.PROMPT_CATALOG,storageKey='inclass.prototype.workbuddy-prompts.v1',settingsKey='inclass.prototype.workbuddy-parameters.v1';
const modules=[{id:'connection',name:'连接',description:'所有模块共用的连接'}, {id:'ppt',name:'PPT管理',description:'新建、更新与分阶段制作'}, {id:'lesson',name:'教案制作',description:'教案内容与Word交付'}, {id:'grade',name:'批改作业',description:'调用参数与批改要求'}, {id:'questionnaire',name:'问卷管理',description:'问卷初版生成要求'}];
const moduleOf=item=>item.id==='lesson'?'lesson':item.id==='grade'?'grade':item.id==='questionnaire'?'questionnaire':'ppt';
const gradeDefaults={model:'default',timeout:60,background:true,noHistory:true,keepRaw:false};
let saved={},parameters={},currentModule='grade',current=catalog.find(i=>i.id==='grade'),drafts={},pending=null,toastTimer;
function load(key){try{const value=JSON.parse(localStorage.getItem(key)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{$('storageError').textContent='无法读取本地原型设置，已展示默认值。保存前请检查浏览器存储权限。';return {};}}
const old=load(storageKey);for(const item of catalog)if(typeof old[item.id]==='string'&&old[item.id].length<=20000)saved[item.id]=old[item.id];
parameters=load(settingsKey);
function entries(){return catalog.filter(item=>moduleOf(item)===currentModule);}
function stash(){if(currentModule!=='connection')drafts[current.id]=$('prompt').value;}
function gradeValues(){return {model:$('model').value,timeout:$('timeout').value,background:$('optBg').checked,noHistory:$('optHist').checked,keepRaw:$('optRaw').checked};}
function gradeBase(){const value={...gradeDefaults,...parameters.grade};return {...value,timeout:String(value.timeout)};}
function dirty(){if(currentModule==='connection')return false;stash();return entries().some(item=>drafts[item.id]!==undefined&&drafts[item.id] !== (saved[item.id]??item.text))||(currentModule==='grade'&&JSON.stringify(gradeValues())!==JSON.stringify(gradeBase()));}
function toast(text){$('toast').textContent=text;$('toast').classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('on'),3000);}
function status(){const changed=dirty();$('state').textContent=changed?'有未保存的参数':'仅用于原型';$('count').textContent=$('prompt').value.length+' / 20000 字';$('save').disabled=!changed;$('discard').disabled=!changed;$('reset').disabled=$('prompt').value===current.text;
 document.querySelectorAll('[data-module]').forEach(b=>{const active=b.dataset.module===currentModule;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 document.querySelectorAll('[data-id]').forEach(b=>{const item=catalog.find(i=>i.id===b.dataset.id);b.classList.toggle('active',item===current);b.setAttribute('aria-pressed',String(item===current));const changed=drafts[item.id]!==undefined&&drafts[item.id] !== (saved[item.id]??item.text);b.querySelector('small').textContent=changed?'未保存':saved[item.id]===undefined?'跟随默认':'已自定义';});
 $('syncStatus').textContent=saved[current.id]===undefined?'跟随模块默认提示词；默认内容更新后自动使用最新版。':'此项使用你的自定义内容。默认内容更新时保留你的修改，可通过恢复默认重新跟随。';
}
function renderPrompt(item){current=item;$('group').textContent=item.group;$('promptTitle').textContent=item.title;$('source').textContent='代码来源：server/'+item.source;$('prompt').value=drafts[item.id]??saved[item.id]??item.text;$('variables').textContent=item.variables;$('fixed').textContent=item.fixed;$('raw').textContent=item.raw;$('error').textContent='';$('prompt').removeAttribute('aria-invalid');status();}
function renderModule(id){currentModule=id;drafts={};const module=modules.find(m=>m.id===id);$('title').textContent=module.name;$('moduleDescription').textContent=module.description;$('connection').hidden=id!=='connection';$('business').hidden=id==='connection';$('gradeParameters').hidden=id!=='grade';$('otherParameters').hidden=id==='grade';$('otherParameters').textContent='本模块的课程、课时、资料等任务参数仍在制作页面填写；此处管理可复用的生成要求。';
 if(id==='grade'){const p=gradeBase();$('model').value=p.model;$('timeout').value=p.timeout;$('optBg').checked=p.background;$('optHist').checked=p.noHistory;$('optRaw').checked=p.keepRaw;}
 $('parameterError').textContent='';$('subfunctions').replaceChildren();if(id!=='connection'){let group='';for(const item of entries()){if(item.group!==group&&id==='ppt'){const heading=document.createElement('p');heading.className='subgroup';heading.textContent=item.group;$('subfunctions').append(heading);group=item.group;}const b=document.createElement('button');b.dataset.id=item.id;b.append(document.createTextNode(item.title));b.append(document.createElement('small'));b.onclick=()=>{stash();renderPrompt(item);};$('subfunctions').append(b);}renderPrompt(entries()[0]);}else{document.querySelectorAll('[data-module]').forEach(b=>{b.classList.toggle('active',b.dataset.module===id);b.setAttribute('aria-pressed',String(b.dataset.module===id));});}}
function confirmAction(title,text,label,fn){pending=fn;$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmAction').textContent=label;$('confirm').showModal();$('keep').focus();}
function guard(fn){if(!dirty())return fn();confirmAction('放弃尚未保存的参数？','「'+modules.find(m=>m.id===currentModule).name+'」的参数与提示词修改尚未保存。放弃后回到上次保存的版本，其他模块不受影响。','放弃修改并继续',fn);}
for(const module of modules){const b=document.createElement('button');b.dataset.module=module.id;b.append(document.createTextNode(module.name));const small=document.createElement('small');small.textContent=module.description;b.append(small);b.onclick=()=>{if(module.id!==currentModule)guard(()=>renderModule(module.id));};$('catalog').append(b);}
$('prompt').oninput=()=>{$('error').textContent='';$('prompt').removeAttribute('aria-invalid');status();};
for(const id of ['model','timeout','optBg','optHist','optRaw'])$(id).addEventListener('input',()=>{$('parameterError').textContent='';status();});
$('save').onclick=()=>{stash();if(currentModule==='grade'){const timeout=Number($('timeout').value);if(!Number.isInteger(timeout)||timeout<1||timeout>7200){$('parameterError').textContent='单份超时请输入1至7200之间的整数（秒）。';$('timeout').focus();return;}}
 for(const item of entries()){const text=drafts[item.id]??saved[item.id]??item.text;let error='';if(!text.trim())error='请填写教学要求，不能保存空白提示词。';else if(text.length>20000)error='教学要求最多20000字，请精简后保存。';else if(item.id==='lesson'&&!text.includes('{{课时分钟}}'))error='请保留必要变量 {{课时分钟}}，用于与教师设置的总课时一致。';if(error){renderPrompt(item);$('error').textContent=error;$('prompt').setAttribute('aria-invalid','true');$('prompt').focus();return;}}
 const next={...saved};for(const item of entries()){const text=drafts[item.id]??saved[item.id]??item.text;if(text===item.text)delete next[item.id];else next[item.id]=text;}const nextParams={...parameters};if(currentModule==='grade')nextParams.grade={...gradeValues(),timeout:Number($('timeout').value)};
 // One local record commits all module parameters and prompts together; legacy key is read only for migration.
 try{localStorage.setItem('inclass.prototype.workbuddy-module-settings.v2',JSON.stringify({prompts:next,parameters:nextParams}));saved=next;parameters=nextParams;drafts={};$('storageError').textContent='';status();toast('本模块参数已保存，仅用于此浏览器原型');}catch{$('storageError').textContent='本地保存失败，请检查浏览器存储权限或空间后重试。当前输入已保留。';}};
$('discard').onclick=()=>guard(()=>{renderModule(currentModule);toast('已放弃本模块修改');});
$('reset').onclick=()=>confirmAction('恢复「'+current.title+'」的默认提示词？','仅替换当前子功能的提示词；其他子功能与调用参数保留。保存模块参数后生效。','恢复默认提示词',()=>{$('prompt').value=current.text;$('error').textContent='';$('prompt').removeAttribute('aria-invalid');status();toast('已载入默认提示词，请保存模块参数');});
$('keep').onclick=()=>{$('confirm').close();pending=null;};$('confirmAction').onclick=()=>{const fn=pending;pending=null;$('confirm').close();if(fn)fn();};$('confirm').addEventListener('cancel',()=>pending=null);
window.addEventListener('beforeunload',event=>{if(dirty()){event.preventDefault();event.returnValue='';}});
document.querySelectorAll('a').forEach(a=>a.addEventListener('click',event=>{if(!dirty())return;event.preventDefault();guard(()=>{renderModule(currentModule);location.href=a.href;});}));
const combined=load('inclass.prototype.workbuddy-module-settings.v2');if(combined.prompts&&typeof combined.prompts==='object'&&combined.parameters&&typeof combined.parameters==='object'){for(const item of catalog){if(typeof combined.prompts[item.id]==='string')saved[item.id]=combined.prompts[item.id];else delete saved[item.id];}parameters=combined.parameters;}
renderModule(currentModule);
